import{d as c,C as t,o as m,c as u,j as a,a as s,E as r,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const q=JSON.parse('{"title":"道德经第二十九章","description":"从天下神器、为执之失到物情不同，理解去甚去奢去泰。","frontmatter":{"title":"道德经第二十九章","description":"从天下神器、为执之失到物情不同，理解去甚去奢去泰。","category":"guide","aliases":["道德经第二十九章","老子第二十九章","dao de jing chapter 29"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-29.md","filePath":"daoism/dao-de-jing/chapter-29.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-29.md"},_=c({...p,setup(b){const o=[{id:"trying-to-make-the-world",label:"将欲取天下而为之，吾见其不得已",showLabel:!0,sentences:[["将欲取天下而",{text:"为",glossary:"wei"},"之，吾见其",{text:"不得已",glossary:"budeyi"},"。"]],note:["【白话】想要取得天下，并照自己的意志强行经营改造它，我看这样不能得逞。开头直接指出，取得与操控天下之间有不可随意跨越的限度。","【王弼注择要】后文注说「物有常性，而造为之，故必败也」。本页据此理解这里的为，重点在另加造作，不是把一切参与和承担都判为错。","【读法】不得已在本句暂取不能达到目的、已为句末语助的读法，区别于第三十章迫于必要的不得已；取天下也不只是一种个人修心的比喻。"]},{id:"spiritual-vessel-and-grasping",label:"天下神器，不可为也，不可执也",showLabel:!0,sentences:[["天下",{text:"神器",glossary:"shenqi"},"，不可为也，不可",{text:"执",glossary:"zhi"},"也。"],["为者败之，执者失之。"]],note:["【白话】天下是微妙而合成的整体，不能任意造作，也不能牢牢执据。强行造作便会败坏它，固执占持便会失去它。","【王弼注择要】「神，无形无方也。器，合成也。」注又说「万物以自然为性，故可因而不可为也，可通而不可执也」，将顺应、通达与强造、执持区别开。","【读法】神器在这里不是神奇宝物或可随意操纵的器械；依注说微妙合成。执所批评的固持，也不等于所有持续的承诺或必要的规则。"]},{id:"diverse-conditions",label:"故物或行或随，或歔或吹",showLabel:!0,sentences:[["故物或行或随，或",{text:"歔",glossary:"xu"},"或吹，或",{text:"强",glossary:"qiang"},"或",{text:"羸",glossary:"lei"},"，或",{text:"载",glossary:"zai"},"或",{text:"隳",glossary:"hui"},"。"]],note:["【白话】所以事物有的先行，有的随后；有的缓嘘，有的急吹；有的强盛，有的羸弱；有的承载安立，有的毁坏坠落。这里把不同情势并列，不能一概强制。","【王弼注择要】「凡此诸或，言物事逆顺反覆。」前面又说「物有往来，而执之，故必失矣」，将诸或连到物情与往来变化。","【读法】歔、吹本页借呼吸的缓急对举，也有从出气冷暖解释的路向。载字仍存疑，本页暂以承载安立与隳对读；所据录文作挫，不隐去差异。"]},{id:"removing-excess",label:"是以圣人去甚，去奢，去泰",showLabel:!0,sentences:[["是以圣人",{text:"去",glossary:"qu"},{text:"甚",glossary:"shen"},"，去",{text:"奢",glossary:"she"},"，去",{text:"泰",glossary:"tai"},"。"]],note:["【白话】因此圣人去掉过甚，去掉奢侈，去掉过分骄纵、安泰自满的做法。结尾给出的行动方向，是减少造成压迫与迷惑的过度作为。","【王弼注择要】「因而不为，顺而不施，除其所以迷，去其所以惑。」王弼并未把顺物写成全不处理，而是强调所去与所除不离物情。","【读法】去读 qù，作除去；甚、奢、泰是应去的过度状态。去泰不等于反对所有安定生活，自然也不能成为不辨伤害、任其持续的理由。"]}],i=[{id:"wei",term:"为",sense:1},{id:"budeyi",term:"不得已",sense:1},{id:"shenqi",term:"神器",sense:1},{id:"zhi",term:"执",sense:1},{id:"xu",term:"歔",sense:1},{id:"qiang",term:"强",sense:2,pinyin:"qiáng"},{id:"lei",term:"羸",sense:1},{id:"zai",term:"载",sense:1},{id:"hui",term:"隳",sense:1},{id:"qu",term:"去",sense:1},{id:"shen",term:"甚",sense:1},{id:"she",term:"奢",sense:1},{id:"tai",term:"泰",sense:1}];return(x,e)=>{const n=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二十九章",tabindex:"-1"},[s("道德经第二十九章 "),a("a",{class:"header-anchor",href:"#道德经第二十九章","aria-label":'Permalink to "道德经第二十九章"'},"​")],-1)),r(n,{title:"天下不能任意塑造，怎样面对不同的物情",summary:"欲取天下而为之，先遭到不得的判断；神器不可为执的说法，再由事物的不同状态展开，最后落在去甚、去奢、去泰。",points:[{label:"先读",text:"分清一般行动与以己意强造、执持的为，避免把全章读成不做任何事。"},{label:"再辨",text:"四组或句说物情有异、有往来，不必压成一条相同进度。"},{label:"后看",text:"三去仍然要求有所行动，关键在去掉过甚与过度伸张。"}],hint:"本站保留载字，所据录文作挫，此处暂读与存疑会注明；强在本章读 qiáng。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:o,glossary:i}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"天下神器，不可为也，不可执也。",tone:"强造的限度",guide:"先循神无形无方、器合成理解，再看为与执为何可能损伤整体。"},{text:"故物或行或随，或歔或吹，或强或羸，或载或隳。",tone:"物情不一",guide:"几个或并列不同状态，不把所有事物固定成一种步调。"},{text:"是以圣人去甚，去奢，去泰。",tone:"仍有所去",guide:"结尾不是取消行动，而是为行动指出减少过度、顺应物情的方向。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:i}),e[4]||(e[4]=g('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-天下神器与四组或句有什么关系" tabindex="-1">象：天下神器与四组或句有什么关系？ <a class="header-anchor" href="#象-天下神器与四组或句有什么关系" aria-label="Permalink to &quot;象：天下神器与四组或句有什么关系？&quot;">​</a></h3><p>神器先说明天下不适合按一个人的定式任意造作，或句再展开事物实际存在的差异与变化。若忽略这些物情而强行执持，就容易败坏本想成就的整体。</p><h3 id="理-不可为为什么还能去甚、去奢、去泰" tabindex="-1">理：不可为为什么还能去甚、去奢、去泰？ <a class="header-anchor" href="#理-不可为为什么还能去甚、去奢、去泰" aria-label="Permalink to &quot;理：不可为为什么还能去甚、去奢、去泰？&quot;">​</a></h3><p>这里的为经王弼解释为造为、强施，不包括一切因势处理。三去说明仍需去掉过度之处；是否有所作为，与是否强以己意制物，不是同一个问题。</p><h3 id="用-尊重差异是否意味着永远不设标准" tabindex="-1">用：尊重差异是否意味着永远不设标准？ <a class="header-anchor" href="#用-尊重差异是否意味着永远不设标准" aria-label="Permalink to &quot;用：尊重差异是否意味着永远不设标准？&quot;">​</a></h3><p>现实协作仍需共同目标、最低要求和责任约定。可以检查标准是否回应真实需要，是否允许不同条件下的合理路径，再修正过度控制，不必取消所有规则。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>先看情势，再定步调。</strong> 同一任务中的人和环节可能处于不同阶段。先识别依赖、能力与风险，再决定统一哪些要求、保留哪些差别。</p><p><strong>检查规则是否越过目的。</strong> 一项措施若不断制造额外负担，却很少改善原来的问题，可以重新评估它。三去提供反省过度的方向，具体改动仍应依据事实和后果。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我坚持的一个统一要求，正在帮助大家成事，还是只让事情看起来符合我的想象？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「不可执也」及「或载或隳」；所据 HFL 录文在该组正文未列不可执也，后文见执者失之；四对末组作「或挫或隳」。不依单份电子录文默删、默改本站正文。</li><li>载字句义有分歧，本页暂以承载安立与毁坠对读，仍列存疑；歔吹也交代不同解释，不据任一取法构造确定规律。</li><li>不得已在本句与第三十章迫于必要义分开；为按造为、强施理解，强取强盛义读 qiáng。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，007a–007b</a>。</p>',15))])}}});export{q as __pageData,_ as default};
